using BattleShip.Domain;
namespace BattleShip.Application;
public interface IBotStrategy { Cell ChooseTarget(Board enemyBoard); void ProcessResult(Cell target,ShotResult result); }
public sealed class RandomBot:IBotStrategy { private readonly Random _random=new(); public Cell ChooseTarget(Board b)=>Unshot(b).OrderBy(_=>_random.Next()).First(); public void ProcessResult(Cell t,ShotResult r){} public static IEnumerable<Cell> Unshot(Board b)=>Enumerable.Range(0,10).SelectMany(r=>Enumerable.Range(0,10).Select(c=>new Cell(r,c))).Where(c=>!b.WasShot(c)); }
public sealed class HuntTargetBot:IBotStrategy { private readonly RandomBot _hunt=new(); private readonly Queue<Cell> _targets=[]; private readonly HashSet<Cell> _hits=[]; public Cell ChooseTarget(Board b){while(_targets.Count>0){var c=_targets.Dequeue();if(!b.WasShot(c))return c;}return _hunt.ChooseTarget(b);} public void ProcessResult(Cell t,ShotResult r){if(r is ShotResult.Hit or ShotResult.Sunk or ShotResult.GameOver){_hits.Add(t);foreach(var c in t.Neighbors4())if(!_hits.Contains(c))_targets.Enqueue(c);}if(r is ShotResult.Sunk or ShotResult.GameOver){_targets.Clear();_hits.Clear();}} }
public sealed class ProbabilityBot:IBotStrategy { private readonly HuntTargetBot _target=new(); public Cell ChooseTarget(Board b){var scores=new Dictionary<Cell,int>();foreach(var (_,len) in Fleet.Default)foreach(var r in Enumerable.Range(0,10))foreach(var c in Enumerable.Range(0,10))foreach(var o in Enum.GetValues<Orientation>())if(b.CanFitUnknownShip(len,new(r,c),o))foreach(var cell in Board.GetCells(len,new(r,c),o))if(!b.WasShot(cell))scores[cell]=scores.GetValueOrDefault(cell)+1;return scores.Count==0?_target.ChooseTarget(b):scores.OrderByDescending(x=>x.Value).ThenBy(x=>x.Key.Row).ThenBy(x=>x.Key.Column).First().Key;}public void ProcessResult(Cell t,ShotResult r)=>_target.ProcessResult(t,r); }
